    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    strong_prev = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = float(prev['bid'])
            prev_bids.append(bid)
            if bid > strong_prev:
                strong_prev = bid

    alive_count = len(alive_opponents) + 1
    tight_supply = supply <= WATER_REQ * 1.5
    very_tight_supply = supply <= WATER_REQ * 1.2

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if very_tight_supply:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if day >= 8:
        urgency += 1

    if strong_prev >= 150:
        market_mode = 'hyper'
    elif strong_prev >= 90:
        market_mode = 'high'
    elif strong_prev >= 40:
        market_mode = 'medium'
    else:
        market_mode = 'low'

    if urgency >= 6:
        bid = max(DAILY_SALARY * 1.8, strong_prev + 6.0)
    elif urgency >= 4:
        if market_mode == 'hyper':
            bid = strong_prev + 4.0
        elif market_mode == 'high':
            bid = max(DAILY_SALARY * 1.25, strong_prev + 3.0)
        else:
            bid = max(DAILY_SALARY * 0.95, strong_prev + 2.0)
    elif urgency >= 2:
        if market_mode == 'hyper':
            bid = DAILY_SALARY * 0.55
        elif market_mode == 'high':
            bid = DAILY_SALARY * 0.75
        elif market_mode == 'medium':
            bid = max(DAILY_SALARY * 0.6, strong_prev + 1.5)
        else:
            bid = DAILY_SALARY * 0.5
    else:
        if market_mode == 'hyper':
            bid = DAILY_SALARY * 0.18
        elif market_mode == 'high':
            bid = DAILY_SALARY * 0.28
        elif market_mode == 'medium':
            bid = DAILY_SALARY * 0.4
        else:
            bid = DAILY_SALARY * 0.22

    rich_aggressive = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if prev and prev.get('bid') is not None:
            prev_bid = float(prev['bid'])
        if opp.get('budget', 0) > budget and prev_bid >= 100:
            rich_aggressive += 1

    if rich_aggressive >= 2 and urgency <= 2:
        bid *= 0.7
    elif rich_aggressive >= 1 and urgency <= 1:
        bid *= 0.8

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, strong_prev + 2.5 if strong_prev > 0 else DAILY_SALARY * 0.9))

    if budget < DAILY_SALARY:
        bid = min(bid, budget)
    elif budget < 2 * DAILY_SALARY and urgency <= 1:
        bid = min(bid, DAILY_SALARY * 0.45)

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    # Estimate how many opponents alive
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponents
    yesterday_bids = []
    for opp_id, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default base bid
    base_bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If opponent bid very high yesterday, they might be broke today -> bid low
        if max_prev > DAILY_SALARY * 1.8:  # ~162
            base_bid = DAILY_SALARY * 0.3
        else:
            # Otherwise, bid slightly above their max if we have low HP
            if hp <= 2:
                base_bid = min(max_prev + 2, budget)
            else:
                base_bid = max(DAILY_SALARY * 0.5, max_prev - 5)

    # Adjust for my health and supply
    if hp <= 2:
        # desperate – bid up to budget but not too high if supply is high
        if supply >= 20:
            target = min(budget, DAILY_SALARY * 0.7)
        else:
            target = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 5:
        if supply >= 20:
            target = min(budget, DAILY_SALARY * 0.4)
        else:
            target = min(budget, DAILY_SALARY * 0.6)
    else:
        if supply >= 20:
            target = min(budget, DAILY_SALARY * 0.3)
        else:
            target = min(budget, DAILY_SALARY * 0.5)

    # Combine: take the higher of base and target
    bid = max(base_bid, target)
    # Ensure we don't exceed budget
    bid = min(bid, budget)
    # Round to 2 decimals
    return round(bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Identify alive opponents and read yesterday's bid
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Estimate how many full water units exist; use int indices only if needed
    # (Not indexing here, but keep logic float-safe)
    expected_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Pressure from yesterday: Cindy-like players bid very high and survived.
    # Use quantiles via thresholds rather than sorting for simplicity.
    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev = 0.0
    if len(yesterday_bids) >= 2:
        # compute second highest safely
        sorted_b = sorted(yesterday_bids)
        second_prev = float(sorted_b[-2])

    # Core strategy:
    # - If yesterday highest was very high, bid just above second-highest to avoid Cindy's extreme spending.
    # - If yesterday bids were low, bid moderate to ensure we win.
    # - Adjust by my hp: if low hp, be more aggressive.

    # Base bid target depends on supply abundance
    if supply >= 22.0:
        base = DAILY_SALARY * 0.55
    elif supply >= 18.0:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.75

    if highest_prev >= DAILY_SALARY * 0.85:
        # Cindy-like: avoid going all-in; target above second-highest
        target = max(base, second_prev + 5.0)
    elif highest_prev >= DAILY_SALARY * 0.45:
        # Alex-like moderate pressure
        target = max(base * 0.95, highest_prev + 2.0)
    else:
        # Bob/David-like low bids
        target = max(base * 0.75, highest_prev + 8.0)

    # HP urgency
    if my_hp <= 2.0:
        target *= 1.15
    elif my_hp <= 4.0:
        target *= 1.05

    # Budget cap: never exceed what we can pay
    # Also keep some reserve for later days: reserve fraction grows when hp is healthy.
    if my_hp >= 7.0:
        reserve_frac = 0.35
    elif my_hp >= 4.0:
        reserve_frac = 0.25
    else:
        reserve_frac = 0.15

    max_affordable = my_budget * (1.0 - reserve_frac)
    bid = float(min(my_budget, max_affordable, target))

    # Ensure bid is non-negative
    if bid < 0.0:
        bid = 0.0

    return bid
